def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with cwd if path is relative, otherwise start with /
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent
            if current == '':
                current = ''
            else:
                parts = current.rstrip('/').split('/')
                if len(parts) > 1:
                    current = '/'.join(parts[:-1])
                else:
                    current = ''
            i += 1
            continue

        # Append the component
        if current == '':
            new_path = '/' + component
        else:
            new_path = current + '/' + component

        # Check if this path is a symlink
        if new_path in links:
            # We've encountered a symlink
            link_count += 1
            if link_count > 8:
                return None

            target = links[new_path]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = ''
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                if new_path == '':
                    link_dir = ''
                else:
                    parts = new_path.rstrip('/').split('/')
                    if len(parts) > 1:
                        link_dir = '/'.join(parts[:-1])
                    else:
                        link_dir = ''

                current = link_dir
                target_components = target.split('/')

            # Insert target components at current position
            components = target_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just update current
        current = new_path
        i += 1

    # Return the canonical path
    if current == '':
        return '/'
    else:
        return current

